//! The 7 x 7 median (`cv2.medianBlur`, ksize 7, replicated border) on sixteen output pixels at
//! a time, exact: sorting networks on `u8` lanes instead of Huang's per-pixel histogram.
//!
//! Per output row the 7 window rows are sorted column by column (`sort7`); the sorted columns
//! of three neighbours are merged (`t3`) and the median of the window, columns `o..o + 6`, is
//! the 25th smallest of `t3(o)`, `t3(o + 4)` and column `o + 3` (`select`). The networks are
//! generated by `tools/gen_median_net.py` and checked there on all 0-1 inputs.

use crate::median_net::{select, sort7, t3};
use crate::simd::{load, store, V};

const LANES: usize = 16;

/// `src[i..i + 16]` as a vector.
///
/// The callers assert once per stage that every index they pass stays in bounds.
#[inline(always)]
fn ld(buf: &[u8], i: usize) -> V {
    debug_assert!(i + LANES <= buf.len());
    // SAFETY: `i + 16 <= buf.len()`, asserted by the caller's stage bounds.
    unsafe { load(buf.as_ptr().add(i)) }
}

#[inline(always)]
fn st(buf: &mut [u8], i: usize, v: V) {
    debug_assert!(i + LANES <= buf.len());
    // SAFETY: as `ld`.
    unsafe { store(buf.as_mut_ptr().add(i), v) }
}

/// Median of the 7 x 7 window around every pixel of a `h x w` image, replicated border.
pub fn median7(src: &[u8], h: usize, w: usize) -> Vec<u8> {
    assert_eq!(src.len(), h * w);
    let mut out = vec![0u8; h * w];
    if h == 0 || w == 0 {
        return out;
    }
    // `nv` output vectors per row; the planes are `l` long: the sorted columns are read up to
    // `16 * (nv + 1) + 2` and the merged triples up to `16 * nv + 3`.
    let nv = w.div_ceil(LANES);
    let l = LANES * (nv + 2);
    // rows with 3 replicated pixels on the left and the last pixel repeated to the right
    let mut pad = vec![0u8; h * l];
    for (p, s) in pad.chunks_exact_mut(l).zip(src.chunks_exact(w)) {
        p[..3].fill(s[0]);
        p[3..3 + w].copy_from_slice(s);
        p[3 + w..].fill(s[w - 1]);
    }
    let mut cols = vec![0u8; 7 * l]; // sorted columns, plane i = i-th smallest
    let mut trip = vec![0u8; 21 * l]; // merged triples of columns
    let mut tail = [0u8; LANES];
    for y in 0..h {
        let rows: [&[u8]; 7] = std::array::from_fn(|i| {
            let r = (y + i).saturating_sub(3).min(h - 1);
            &pad[r * l..(r + 1) * l]
        });
        for j in 0..nv + 2 {
            let x = j * LANES;
            let c = sort7(std::array::from_fn(|i| ld(rows[i], x)));
            for (i, v) in c.into_iter().enumerate() {
                st(&mut cols, i * l + x, v);
            }
        }
        for j in 0..nv + 1 {
            let x = j * LANES;
            let c = |d: usize| -> [V; 7] { std::array::from_fn(|i| ld(&cols, i * l + x + d)) };
            let t = t3(c(0), c(1), c(2));
            for (i, v) in t.into_iter().enumerate() {
                st(&mut trip, i * l + x, v);
            }
        }
        let row = &mut out[y * w..(y + 1) * w];
        for j in 0..nv {
            let x = j * LANES;
            let m = select(
                std::array::from_fn(|i| ld(&trip, i * l + x)),
                std::array::from_fn(|i| ld(&trip, i * l + x + 4)),
                std::array::from_fn(|i| ld(&cols, i * l + x + 3)),
            );
            if x + LANES <= w {
                st(row, x, m);
            } else {
                st(&mut tail, 0, m);
                row[x..].copy_from_slice(&tail[..w - x]);
            }
        }
    }
    out
}
